{# =====================================================================
   DAILY OPERATIONS REVIEW · Print Format on "DRI Production" (Custom Format, Jinja)
   Three landscape pages for one day (6 AM to 6 AM): production (DRI + power plant),
   sales, weighbridge. Month-to-date (MTD) figures are shown for reference only;
   monthly analysis belongs in the monthly report.
   ===================================================================== #}

{# ---------- Settings ---------- #}
{% set COMPANY = "NACHIKETA POWER AND STEEL PVT LTD" %}
{% set TARGET_MT_MONTH = 15000 %}          {# monthly DRI target, MT (daily target = this ÷ days in month) #}
{% set TARGET_MW = 14 %}                   {# average MW generated per day #}
{% set SALES_ITEMS = ["FG-0001"] %}        {# items the sales page reports on #}
{% set MIN_DOC_VALUE = 50000 %}            {# invoices / orders below this net value are left out, as on the dashboard #}
{% set MIN_OUTSTANDING = 1000000 %}        {# receivables table lists customers owing at least this #}
{% set AGE_DAYS = [5, 10, 20] %}           {# receivables ageing buckets (days past due) #}
{% set DAY_START = "06:00:00" %}           {# weighbridge day starts at 6 AM #}

{# ---------- Dates ---------- #}
{% set U = frappe.utils %}
{% set day = U.getdate(doc.production_date) %}
{% set next_day = U.add_days(day, 1) %}
{% set mstart = U.get_first_day(day) %}
{% set dim = U.get_last_day(day).day %}
{% set ws = day|string ~ " " ~ DAY_START %}
{% set we = next_day|string ~ " " ~ DAY_START %}
{% set target_day = TARGET_MT_MONTH / dim %}
{% set target_mtd = TARGET_MT_MONTH * day.day / dim %}
{% set items_label = SALES_ITEMS|join(", ") %}

{# ---------- Formatting ---------- #}
{% macro n0(v) %}{% if v is none %}–{% else %}{{ "{:,.0f}".format(v|float) }}{% endif %}{% endmacro %}
{% macro n1(v) %}{% if v is none %}–{% else %}{{ "{:,.1f}".format(v|float) }}{% endif %}{% endmacro %}
{% macro n2(v) %}{% if v is none %}–{% else %}{{ "{:,.2f}".format(v|float) }}{% endif %}{% endmacro %}
{% macro n3(v) %}{% if v is none %}–{% else %}{{ "{:,.3f}".format(v|float) }}{% endif %}{% endmacro %}
{% macro pc(v) %}{% if v is none %}–{% else %}{{ "{:,.1f}".format(v|float) }}%{% endif %}{% endmacro %}
{% macro cr(v) %}{% if v is none %}–{% else %}{{ "{:,.2f}".format((v|float) / 10000000) }}{% endif %}{% endmacro %}
{% macro inr(v) %}{% if v is none %}–{% elif (v|float)|abs >= 100000 %}₹{{ "{:,.2f}".format((v|float) / 10000000) }} Cr{% else %}₹{{ "{:,.0f}".format(v|float) }}{% endif %}{% endmacro %}
{# a ÷ b (× k), formatted; "–" when b is zero #}
{% macro div(a, b, fmt="n2", k=1) %}{% if (b or 0)|float != 0 %}{% set v = ((a or 0)|float) * k / (b|float) %}{% if fmt == "n0" %}{{ n0(v) }}{% elif fmt == "n1" %}{{ n1(v) }}{% elif fmt == "n3" %}{{ n3(v) }}{% elif fmt == "pc" %}{{ pc(v) }}{% else %}{{ n2(v) }}{% endif %}{% else %}–{% endif %}{% endmacro %}
{# quantile with linear interpolation, as on the dashboard #}
{% macro qtl(arr, p) %}{% if arr %}{% set s = arr|sort %}{% set n = (s|length - 1) * p %}{% set i = n|int %}{% set j = [i + 1, s|length - 1]|min %}{{ n0(s[i] + (s[j] - s[i]) * (n - i)) }}{% else %}–{% endif %}{% endmacro %}

{# =====================================================================
   DATA
   ===================================================================== #}

{# ---------- DRI Production ---------- #}
{% set P_COLS = "
  COUNT(DISTINCT production_date) AS days,
  SUM(CASE WHEN docstatus = 0 THEN 1 ELSE 0 END) AS drafts,
  SUM(IFNULL(dri_production,0)) AS dri,
  SUM(IFNULL(cons_pellets,0)) AS pel,
  SUM(CASE WHEN IFNULL(cons_pellets,0) > 0 THEN IFNULL(dri_production,0) ELSE 0 END) AS pel_p,
  SUM(IFNULL(cons_sized_ore,0)) AS ore,
  SUM(CASE WHEN IFNULL(cons_sized_ore,0) > 0 THEN IFNULL(dri_production,0) ELSE 0 END) AS ore_p,
  SUM(IFNULL(grade_a_hrs,0)) AS a_hrs,
  SUM(IFNULL(grade_a_hrs,0) + IFNULL(grade_b_hrs,0)) AS ab_hrs,
  SUM(IFNULL(cons_rb2,0) + IFNULL(cons_washed,0) + IFNULL(cons_rom_b,0) + IFNULL(cons_rb1,0)) AS coal,
  SUM(IFNULL(cons_pellets,0) + IFNULL(cons_sized_ore,0)) AS iron,
  SUM(IFNULL(cons_dolomite,0)) AS dolo,
  SUM(IFNULL(cons_rb2,0) * IFNULL(rb2_fc,0) + IFNULL(cons_washed,0) * IFNULL(dom2_fc,0) + (IFNULL(cons_rom_b,0) + IFNULL(cons_rb1,0)) * IFNULL(dom1_fc,0)) AS fc_num,
  SUM(CASE WHEN fe_m > 0 THEN IFNULL(dri_production,0) * fe_m ELSE 0 END) AS fe_num,
  SUM(CASE WHEN fe_m > 0 THEN IFNULL(dri_production,0) ELSE 0 END) AS fe_den,
  SUM(CASE WHEN c > 0 THEN IFNULL(dri_production,0) * c ELSE 0 END) AS c_num,
  SUM(CASE WHEN c > 0 THEN IFNULL(dri_production,0) ELSE 0 END) AS c_den,
  SUM(CASE WHEN s > 0 THEN IFNULL(dri_production,0) * s ELSE 0 END) AS s_num,
  SUM(CASE WHEN s > 0 THEN IFNULL(dri_production,0) ELSE 0 END) AS s_den,
  SUM(CASE WHEN mag_recovery_from_char > 0 THEN IFNULL(char_generation,0) * mag_recovery_from_char ELSE 0 END) AS nm_num,
  SUM(CASE WHEN mag_recovery_from_char > 0 THEN IFNULL(char_generation,0) ELSE 0 END) AS nm_den,
  SUM(IFNULL(power_kwh,0)) AS kwh,
  SUM(IFNULL(power_import_from_grid,0)) AS imp_kwh,
  SUM(IFNULL(dri_power_consumption,0)) AS dri_kwh,
  SUM(IFNULL(pp_power_consumption,0)) AS pp_kwh,
  SUM(IFNULL(power_exported,0)) AS exp_kwh,
  SUM(IFNULL(total_steam,0)) AS steam,
  SUM(IFNULL(steam_to_turbine,0)) AS stt,
  SUM(IFNULL(dm_water_production,0)) AS dm_p,
  SUM(IFNULL(dm_water_consumption,0)) AS dm_c,
  AVG(CASE WHEN power_factor > 0 THEN power_factor END) AS pf,
  AVG(CASE WHEN power_load_factor > 0 THEN power_load_factor END) AS plf,
  AVG(tg_running_hrs) AS tg,
  AVG(whrb_running_hrs) AS whrb,
  AVG(dg_running_hrs) AS dg
" %}
{% set P_FROM = " FROM `tabDRI Production` WHERE docstatus < 2 AND production_date BETWEEN %(f)s AND %(t)s " %}
{% set D = frappe.db.sql("SELECT 'Total' AS kiln," ~ P_COLS ~ P_FROM, {"f": day, "t": day}, as_dict=1)[0] %}
{% set M = frappe.db.sql("SELECT 'Total' AS kiln," ~ P_COLS ~ P_FROM, {"f": mstart, "t": day}, as_dict=1)[0] %}
{% set k_day = frappe.db.sql("SELECT kiln_no AS kiln," ~ P_COLS ~ P_FROM ~ "GROUP BY kiln_no ORDER BY kiln_no", {"f": day, "t": day}, as_dict=1) %}
{% set k_mtd = frappe.db.sql("SELECT kiln_no AS kiln, COUNT(DISTINCT production_date) AS days, SUM(IFNULL(dri_production,0)) AS dri, SUM(IFNULL(power_kwh,0)) AS kwh" ~ P_FROM ~ "GROUP BY kiln_no", {"f": mstart, "t": day}, as_dict=1) %}
{% set km = {} %}{% for r in k_mtd %}{% set _ = km.update({r.kiln: r}) %}{% endfor %}
{# Day by day this month, for the two small charts #}
{% set p_days = frappe.db.sql("SELECT production_date AS d, SUM(IFNULL(dri_production,0)) AS dri, SUM(IFNULL(power_kwh,0)) AS kwh FROM `tabDRI Production` WHERE docstatus < 2 AND production_date BETWEEN %(f)s AND %(t)s GROUP BY production_date", {"f": mstart, "t": day}, as_dict=1) %}
{% set pd = {} %}{% for r in p_days %}{% set _ = pd.update({r.d|string: r}) %}{% endfor %}

{# Remarks and breakdowns from the day's reports #}
{% set dri_notes = [] %}{% set pp_notes = [] %}
{% for name in frappe.get_all("DRI Production", filters={"production_date": day, "docstatus": ["<", 2]}, pluck="name", order_by="kiln_no asc") %}
  {% set rep = frappe.get_doc("DRI Production", name) %}
  {% for r in (rep.get("table_atyf") or []) if r.remarks %}{% set _ = dri_notes.append({"src": rep.kiln_no, "txt": r.remarks}) %}{% endfor %}
  {% for r in (rep.get("power_plant_breakdown") or []) if r.remarks or r.department %}{% set _ = pp_notes.append({"src": rep.kiln_no ~ (" · " ~ r.department if r.department else ""), "txt": r.remarks or "Breakdown recorded"}) %}{% endfor %}
{% endfor %}

{# ---------- Sales (FG-0001) ---------- #}
{% set UOM_MT = "CASE UPPER(TRIM(i.stock_uom)) WHEN 'KG' THEN 0.001 WHEN 'KGS' THEN 0.001 WHEN 'KILOGRAM' THEN 0.001 WHEN 'KILOGRAMS' THEN 0.001 WHEN 'QTL' THEN 0.1 WHEN 'QUINTAL' THEN 0.1 WHEN 'MT' THEN 1 WHEN 'TON' THEN 1 WHEN 'TONS' THEN 1 WHEN 'TONNE' THEN 1 WHEN 'TONNES' THEN 1 WHEN 'METRIC TON' THEN 1 WHEN 'METRIC TONNE' THEN 1 ELSE NULL END" %}
{# Invoiced, by customer, for the day and month to date #}
{% set inv = frappe.db.sql("
  SELECT h.customer AS cust, MAX(h.customer_name) AS name,
         SUM(CASE WHEN h.posting_date = %(day)s THEN i.base_net_amount ELSE 0 END) AS d_amt,
         COALESCE(SUM(CASE WHEN h.posting_date = %(day)s THEN i.stock_qty * " ~ UOM_MT ~ " END), 0) AS d_mt,
         SUM(CASE WHEN h.posting_date = %(day)s AND " ~ UOM_MT ~ " IS NOT NULL THEN i.base_net_amount ELSE 0 END) AS d_wamt,
         COUNT(DISTINCT CASE WHEN h.posting_date = %(day)s THEN h.name END) AS d_n,
         SUM(i.base_net_amount) AS m_amt,
         COALESCE(SUM(i.stock_qty * " ~ UOM_MT ~ "), 0) AS m_mt,
         SUM(CASE WHEN " ~ UOM_MT ~ " IS NOT NULL THEN i.base_net_amount ELSE 0 END) AS m_wamt,
         COUNT(DISTINCT h.name) AS m_n
  FROM `tabSales Invoice Item` i JOIN `tabSales Invoice` h ON h.name = i.parent
  WHERE h.docstatus = 1 AND h.base_net_total >= %(min)s AND i.item_code IN %(items)s
    AND h.posting_date BETWEEN %(m)s AND %(day)s
  GROUP BY h.customer
", {"m": mstart, "day": day, "min": MIN_DOC_VALUE, "items": SALES_ITEMS}, as_dict=1) %}
{% set booked = frappe.db.sql("
  SELECT SUM(CASE WHEN h.transaction_date = %(day)s THEN i.base_net_amount ELSE 0 END) AS d_amt,
         COALESCE(SUM(CASE WHEN h.transaction_date = %(day)s THEN i.stock_qty * " ~ UOM_MT ~ " END), 0) AS d_mt,
         SUM(i.base_net_amount) AS m_amt,
         COALESCE(SUM(i.stock_qty * " ~ UOM_MT ~ "), 0) AS m_mt,
         COUNT(DISTINCT h.name) AS m_n
  FROM `tabSales Order Item` i JOIN `tabSales Order` h ON h.name = i.parent
  WHERE h.docstatus = 1 AND h.base_net_total >= %(min)s AND i.item_code IN %(items)s
    AND h.transaction_date BETWEEN %(m)s AND %(day)s
", {"m": mstart, "day": day, "min": MIN_DOC_VALUE, "items": SALES_ITEMS}, as_dict=1)[0] %}
{# Open orders, any date #}
{% set pend = frappe.db.sql("
  SELECT h.customer AS cust, MAX(h.customer_name) AS name,
         COUNT(DISTINCT h.name) AS n, MIN(h.transaction_date) AS oldest, MIN(h.delivery_date) AS due,
         COALESCE(SUM(i.stock_qty * " ~ UOM_MT ~ "), 0) AS ord_mt,
         COALESCE(SUM(LEAST(IFNULL(i.delivered_qty,0), i.qty) * IFNULL(i.conversion_factor,1) * " ~ UOM_MT ~ "), 0) AS del_mt,
         COALESCE(SUM((i.qty - IFNULL(i.delivered_qty,0)) * IFNULL(i.conversion_factor,1) * " ~ UOM_MT ~ "), 0) AS pend_mt,
         COALESCE(SUM(CASE WHEN h.delivery_date < %(asof)s THEN (i.qty - IFNULL(i.delivered_qty,0)) * IFNULL(i.conversion_factor,1) * " ~ UOM_MT ~ " END), 0) AS late_mt,
         SUM((i.qty - IFNULL(i.delivered_qty,0)) * IFNULL(i.base_net_rate,0)) AS pend_amt
  FROM `tabSales Order Item` i JOIN `tabSales Order` h ON h.name = i.parent
  WHERE h.docstatus = 1 AND h.base_net_total >= %(min)s AND h.status IN ('To Deliver and Bill', 'To Deliver')
    AND i.item_code IN %(items)s AND i.qty > IFNULL(i.delivered_qty,0)
  GROUP BY h.customer
", {"items": SALES_ITEMS, "min": MIN_DOC_VALUE, "asof": next_day}, as_dict=1)|sort(attribute="pend_amt", reverse=true) %}
{# Receivables: all sales invoices (outstanding can't be split by item) #}
{% set AGE = "DATEDIFF(%(asof)s, IFNULL(due_date, posting_date))" %}
{% set ar_cust = frappe.db.sql("
  SELECT customer AS cust, MAX(customer_name) AS name, COUNT(*) AS n, SUM(outstanding_amount) AS amt,
         SUM(CASE WHEN " ~ AGE ~ " <= 0 THEN outstanding_amount ELSE 0 END) AS b0,
         SUM(CASE WHEN " ~ AGE ~ " BETWEEN 1 AND %(a1)s THEN outstanding_amount ELSE 0 END) AS b1,
         SUM(CASE WHEN " ~ AGE ~ " BETWEEN %(a1)s + 1 AND %(a2)s THEN outstanding_amount ELSE 0 END) AS b2,
         SUM(CASE WHEN " ~ AGE ~ " BETWEEN %(a2)s + 1 AND %(a3)s THEN outstanding_amount ELSE 0 END) AS b3,
         SUM(CASE WHEN " ~ AGE ~ " > %(a3)s THEN outstanding_amount ELSE 0 END) AS b4,
         SUM(CASE WHEN outstanding_amount > 0 AND " ~ AGE ~ " > 0 THEN outstanding_amount ELSE 0 END) AS overdue,
         SUM(CASE WHEN outstanding_amount > 0 THEN outstanding_amount ELSE 0 END) AS owed,
         MAX(CASE WHEN outstanding_amount > 0 AND " ~ AGE ~ " > 0 THEN " ~ AGE ~ " END) AS oldest,
         COUNT(CASE WHEN outstanding_amount > 0 AND " ~ AGE ~ " > 0 THEN 1 END) AS n_over
  FROM `tabSales Invoice` WHERE docstatus = 1 AND outstanding_amount != 0
  GROUP BY customer
", {"asof": next_day, "a1": AGE_DAYS[0], "a2": AGE_DAYS[1], "a3": AGE_DAYS[2]}, as_dict=1) %}

{% set S = namespace(d_amt=0, d_mt=0, d_wamt=0, d_n=0, m_amt=0, m_mt=0, m_wamt=0, m_n=0) %}
{% for r in inv %}{% set S.d_amt = S.d_amt + (r.d_amt|float) %}{% set S.d_mt = S.d_mt + (r.d_mt|float) %}{% set S.d_wamt = S.d_wamt + (r.d_wamt|float) %}{% set S.d_n = S.d_n + (r.d_n|int) %}{% set S.m_amt = S.m_amt + (r.m_amt|float) %}{% set S.m_mt = S.m_mt + (r.m_mt|float) %}{% set S.m_wamt = S.m_wamt + (r.m_wamt|float) %}{% set S.m_n = S.m_n + (r.m_n|int) %}{% endfor %}
{% set inv_day = inv|selectattr("d_n", "gt", 0)|sort(attribute="d_amt", reverse=true)|list %}
{% set P = namespace(mt=0, amt=0, late=0, n=0) %}
{% for r in pend %}{% set P.mt = P.mt + (r.pend_mt|float) %}{% set P.amt = P.amt + (r.pend_amt|float) %}{% set P.late = P.late + (r.late_mt|float) %}{% set P.n = P.n + (r.n|int) %}{% endfor %}
{% set R = namespace(amt=0, overdue=0, owed=0, oldest=0, n=0, n_over=0, b0=0, b1=0, b2=0, b3=0, b4=0) %}
{% for r in ar_cust %}
  {% set R.amt = R.amt + (r.amt|float) %}{% set R.overdue = R.overdue + (r.overdue|float) %}{% set R.owed = R.owed + (r.owed|float) %}{% set R.n = R.n + (r.n|int) %}{% set R.n_over = R.n_over + (r.n_over|int) %}
  {% set R.b0 = R.b0 + (r.b0|float) %}{% set R.b1 = R.b1 + (r.b1|float) %}{% set R.b2 = R.b2 + (r.b2|float) %}{% set R.b3 = R.b3 + (r.b3|float) %}{% set R.b4 = R.b4 + (r.b4|float) %}
  {% if (r.oldest or 0)|int > R.oldest %}{% set R.oldest = r.oldest|int %}{% endif %}
{% endfor %}
{% set ar_big = (ar_cust|selectattr("amt", "ge", MIN_OUTSTANDING)|list + ar_cust|selectattr("amt", "le", -MIN_OUTSTANDING)|list)|sort(attribute="amt", reverse=true) %}
{% set ar_small = ar_cust|length - ar_big|length %}

{# ---------- Weighbridge ---------- #}
{% set W_MT = "(CASE WHEN IFNULL(net_weight,0) > 0 THEN net_weight WHEN IFNULL(gross_weight,0) > 0 AND IFNULL(tare_weight,0) > 0 AND gross_weight >= tare_weight THEN gross_weight - tare_weight ELSE 0 END) / 1000.0" %}
{% set W_TAT = "CASE WHEN first_weight_time IS NOT NULL AND second_weight_time >= first_weight_time THEN TIMESTAMPDIFF(MINUTE, first_weight_time, second_weight_time) END" %}
{# Trucks completed in the 6 AM – 6 AM window (by second weighing) #}
{% set wb = frappe.db.sql("SELECT LOWER(TRIM(IFNULL(movement,''))) AS mv, IFNULL(material,'(Unassigned)') AS material, IFNULL(supplier,'(Unassigned)') AS party, " ~ W_MT ~ " AS mt, " ~ W_TAT ~ " AS tat FROM `tabWeighments` WHERE docstatus != 2 AND second_weight_time >= %(ws)s AND second_weight_time < %(we)s", {"ws": ws, "we": we}, as_dict=1) %}
{# Month to date, same rule, for reference in the tiles #}
{% set wm = frappe.db.sql("SELECT LOWER(TRIM(IFNULL(movement,''))) AS mv, " ~ W_MT ~ " AS mt, " ~ W_TAT ~ " AS tat FROM `tabWeighments` WHERE docstatus != 2 AND second_weight_time >= %(f)s AND second_weight_time < %(we)s", {"f": mstart|string ~ " " ~ DAY_START, "we": we}, as_dict=1) %}
{% set waiting = frappe.db.sql("SELECT LOWER(TRIM(IFNULL(movement,''))) AS mv, COUNT(*) AS n FROM `tabWeighments` WHERE docstatus != 2 AND first_weight_time IS NOT NULL AND second_weight_time IS NULL AND first_weight_time >= %(f)s AND first_weight_time < %(we)s GROUP BY LOWER(TRIM(IFNULL(movement,'')))", {"f": U.add_days(day, -2)|string ~ " " ~ DAY_START, "we": we}, as_dict=1) %}
{% set wait = {} %}{% for r in waiting %}{% set _ = wait.update({r.mv: r.n|int}) %}{% endfor %}
{% set wait_n = wait.get("inward", 0) + wait.get("outward", 0) %}

{% set W = {} %}
{% for mv in ["inward", "outward"] %}
  {% set rs = wb|selectattr("mv", "equalto", mv)|list %}
  {% set groups = [] %}
  {% for key, items in rs|groupby("material" if mv == "inward" else "party") %}
    {% set parties = [] %}
    {% if mv == "inward" %}
      {% for pk, pitems in items|groupby("party") %}
        {% set t = pitems|map(attribute="tat")|reject("none")|map("float")|list %}
        {% set _ = parties.append({"name": pk, "trucks": pitems|length, "mt": pitems|sum(attribute="mt"), "tat": (t|sum / t|length) if t else none}) %}
      {% endfor %}
    {% endif %}
    {% set t = items|map(attribute="tat")|reject("none")|map("float")|list %}
    {% set _ = groups.append({"name": key, "trucks": items|length, "mt": items|sum(attribute="mt"), "tat": (t|sum / t|length) if t else none, "parties": parties|sort(attribute="mt", reverse=true)}) %}
  {% endfor %}
  {% set t = rs|map(attribute="tat")|reject("none")|map("float")|list %}
  {% set _ = W.update({mv: {"trucks": rs|length, "mt": rs|sum(attribute="mt"), "tat": (t|sum / t|length) if t else none, "groups": groups|sort(attribute="mt", reverse=true)}}) %}
{% endfor %}
{% set day_tats = wb|map(attribute="tat")|reject("none")|map("float")|list %}
{% set wm_tats = wm|map(attribute="tat")|reject("none")|map("float")|list %}

{# =====================================================================
   PRESENTATION HELPERS
   ===================================================================== #}
{% set day_dri = D.dri|float %}
{% set mtd_dri = M.dri|float %}
{% set m_days = M.days|int %}
{% set day_mw = (D.kwh|float) / 24000 %}
{% set mtd_mw = (M.kwh|float) / (m_days * 24000) if m_days > 0 else 0 %}

{# Column chart. points: [{"l": label, "v": value, "ok": bool}]; bars marked ok=false are amber; target is a dashed line. #}
{% macro chart(points, target, unit, name, w=520, h=150) %}
{% set L = 40 %}{% set B = 16 %}{% set T = 18 %}
{% set vals = points|map(attribute="v")|map("float")|list %}
{% set raw = ([vals|max if vals else 0, target or 0]|max) * 1.05 %}
{% set nm = namespace(top=0) %}
{% for e in range(-1, 10) %}{% for m in [1, 1.5, 2, 2.5, 3, 4, 5, 6, 8] %}{% if nm.top == 0 and m * 10 ** e >= raw %}{% set nm.top = m * 10 ** e %}{% endif %}{% endfor %}{% endfor %}
{% set top = nm.top or 1 %}
{% set ph = h - B - T %}
{% set slot = (w - L - 4) / ([points|length, 1]|max) %}
<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="{{ h }}" viewBox="0 0 {{ w }} {{ h }}" preserveAspectRatio="xMinYMid meet" font-family="Arial, sans-serif">
  {% for k in [0, 0.5, 1] %}{% set y = h - B - ph * k %}
    <line x1="{{ L }}" y1="{{ y }}" x2="{{ w }}" y2="{{ y }}" stroke="#e3e9ec" stroke-width="1"/>
    <text x="{{ L - 4 }}" y="{{ y + 3 }}" font-size="8.5" fill="#617581" text-anchor="end">{{ n0(top * k) if top >= 100 else n1(top * k) }}</text>
  {% endfor %}
  {% for p in points %}{% set x0 = L + slot * loop.index0 %}{% set bh = (p.v|float) / top * ph %}
    <rect x="{{ x0 + slot * 0.15 }}" y="{{ h - B - bh }}" width="{{ slot * 0.7 }}" height="{{ bh }}" rx="1" fill="{{ '#2a78d6' if p.ok else '#e8a33d' }}"/>
    <text x="{{ x0 + slot / 2 }}" y="{{ h - 4 }}" font-size="8" fill="{{ '#172c39' if loop.last else '#617581' }}" text-anchor="middle" font-weight="{{ 'bold' if loop.last else 'normal' }}">{{ p.l }}</text>
  {% endfor %}
  {% if target %}{% set ty = h - B - target / top * ph %}<line x1="{{ L }}" y1="{{ ty }}" x2="{{ w }}" y2="{{ ty }}" stroke="#d1462f" stroke-width="1.5" stroke-dasharray="5,3"/>{% endif %}
  <rect x="{{ L }}" y="3" width="9" height="9" rx="2" fill="#2a78d6"/><text x="{{ L + 13 }}" y="11" font-size="9" fill="#455a66">{{ name }}</text>
  <rect x="{{ L + 24 + (name|length) * 5.2 }}" y="3" width="9" height="9" rx="2" fill="#e8a33d"/><text x="{{ L + 37 + (name|length) * 5.2 }}" y="11" font-size="9" fill="#455a66">below target</text>
  {% if target %}{% set lx = L + 110 + (name|length) * 5.2 %}<line x1="{{ lx }}" y1="7" x2="{{ lx + 16 }}" y2="7" stroke="#d1462f" stroke-width="1.5" stroke-dasharray="5,3"/><text x="{{ lx + 20 }}" y="11" font-size="9" fill="#d1462f">Target {{ n0(target) if target >= 100 else n1(target) }} {{ unit }}</text>{% endif %}
  <line x1="{{ L }}" y1="{{ h - B }}" x2="{{ w }}" y2="{{ h - B }}" stroke="#b8c8cf" stroke-width="1"/>
</svg>
{% endmacro %}

{# Horizontal bars. rows: [{"l": label, "v": number, "t": text, "q": quiet?}] #}
{% macro hbars(rows, empty="Nothing to show.") %}
{% set vals = [] %}{% for r in rows %}{% set _ = vals.append([(r.v or 0)|float, 0]|max) %}{% endfor %}
{% set mx = vals|max if vals else 0 %}
{% if mx > 0 %}
<table class="hb">{% for r in rows %}
  <tr><td class="hb-l">{{ r.l }}</td><td class="hb-t"><div class="hb-track"><div class="hb-fill{{ ' q' if r.q }}" style="width:{{ '%.1f'|format(vals[loop.index0] * 100 / mx) }}%"></div></div></td><td class="hb-v">{{ r.t }}</td></tr>
{% endfor %}</table>
{% else %}<div class="muted" style="padding:8px">{{ empty }}</div>{% endif %}
{% endmacro %}

{% macro tile(label, value, note, status="") %}<td class="tile {{ status }}"><div class="t-label">{{ label }}</div><div class="t-value">{{ value }}</div><div class="t-note">{{ note }}</div></td>{% endmacro %}
{% macro status(v, target) %}{{ "good" if v >= target else ("warn" if v >= 0.9 * target else "bad") }}{% endmacro %}

{% macro head(title, sub) %}
<table class="slide-head"><tr>
  <td><div class="eyebrow">{{ COMPANY }} · DAILY OPERATIONS REVIEW · {{ frappe.format_date(day, "EEEE, dd MMM yyyy") }}</div><div class="s-title">{{ title }}</div></td>
  <td class="s-sub">{{ sub }}</td>
</tr></table>
{% endmacro %}

{% macro notes_box(title, notes, empty) %}
<div class="box">
  <div class="p-title">{{ title }}</div>
  {% if notes %}<table class="notes">{% for n in notes[:5] %}<tr><td class="src">{{ n.src }}</td><td>{{ n.txt }}</td></tr>{% endfor %}</table>{% if notes|length > 5 %}<div class="muted">+ {{ notes|length - 5 }} more in the DRI Production reports</div>{% endif %}
  {% else %}<div class="muted">{{ empty }}</div>{% endif %}
</div>
{% endmacro %}

<style>
