</style>

<div class="dor">

{# ===================== PAGE 1 · PRODUCTION (DRI + POWER PLANT) ===================== #}
<div class="slide">
  {{ head("Production", "6 AM to 6 AM · MTD from " ~ frappe.format_date(mstart, "dd MMM") ~ " for reference · targets " ~ n0(target_day) ~ " MT/day DRI, " ~ TARGET_MW ~ " MW") }}
  {% if (D.drafts|int) > 0 %}<div class="flag">{{ D.drafts }} of the day's production reports are still in draft; figures may change.</div>{% endif %}

  <div class="band">DRI PLANT</div>
  <table class="tiles"><tr>
    {{ tile("DRI production", n0(day_dri) ~ " MT", "Target " ~ n0(target_day) ~ " (" ~ div(day_dri, target_day, "n0", 100) ~ "%) · MTD " ~ n0(mtd_dri) ~ " vs " ~ n0(target_mtd), status(day_dri, target_day)) }}
    {{ tile("Pellet yield", div(D.pel_p, D.pel, "pc", 100), "MTD " ~ div(M.pel_p, M.pel, "pc", 100)) }}
    {{ tile("Iron ore 10–40 yield", div(D.ore_p, D.ore, "pc", 100), "MTD " ~ div(M.ore_p, M.ore, "pc", 100)) }}
    {{ tile('"A" grade', div(D.a_hrs, D.ab_hrs, "pc", 100), "MTD " ~ div(M.a_hrs, M.ab_hrs, "pc", 100)) }}
    {{ tile("Sp. coal", div(D.coal, D.dri) ~ " MT/MT", "MTD " ~ div(M.coal, M.dri) ~ " · F.C. " ~ div(D.fc_num, D.coal, "pc")) }}
    {{ tile("Sp. iron / pellets", div(D.iron, D.dri) ~ " MT/MT", "MTD " ~ div(M.iron, M.dri) ~ " · sp. dolo " ~ div(D.dolo, D.dri, "n3")) }}
    {{ tile("DRI Fe(M)", div(D.fe_num, D.fe_den, "pc"), "C " ~ div(D.c_num, D.c_den) ~ "% · S " ~ div(D.s_num, D.s_den, "n3") ~ "% · non-mag " ~ div(D.nm_num, D.nm_den, "pc")) }}
    {{ tile("Sp. power", div(D.dri_kwh, D.dri, "n0") ~ " units/MT", "MTD " ~ div(M.dri_kwh, M.dri, "n0") ~ " · DRI use " ~ n0((D.dri_kwh|float) / 1000) ~ " MWh") }}
  </tr></table>

  <div class="band">POWER PLANT</div>
  <table class="tiles"><tr>
    {{ tile("Power generated", n2(day_mw) ~ " MW", "Target " ~ TARGET_MW ~ " · MTD " ~ n2(mtd_mw) ~ " MW · " ~ n0((D.kwh|float) / 1000) ~ " MWh", status(day_mw, TARGET_MW)) }}
    {{ tile("Grid import", n1((D.imp_kwh|float) / 1000) ~ " MWh", n2((D.imp_kwh|float) / 24000) ~ " MW avg · export " ~ n1((D.exp_kwh|float) / 1000) ~ " MWh") }}
    {{ tile("Auxiliary consumption", div(D.pp_kwh, D.kwh, "pc", 100), "MTD " ~ div(M.pp_kwh, M.kwh, "pc", 100) ~ " · " ~ n1((D.pp_kwh|float) / 1000) ~ " MWh") }}
    {{ tile("SSC", div(D.stt, (D.kwh|float) / 1000) ~ " t/MWh", "MTD " ~ div(M.stt, (M.kwh|float) / 1000) ~ " · to turbine " ~ n0(D.stt) ~ " t") }}
    {{ tile("Steam generation", n1((D.steam|float) / 24) ~ " TPH", "MTD " ~ div(M.steam, m_days * 24, "n1") ~ " TPH · " ~ n0(D.steam) ~ " t") }}
    {{ tile("Plant load factor", n2(D.plf), "Power factor " ~ n2(D.pf) ~ " · MTD PLF " ~ n2(M.plf)) }}
    {{ tile("Running hours", "TG " ~ n1(D.tg) ~ " h", "WHRB " ~ n1(D.whrb) ~ " h · DG " ~ n1(D.dg) ~ " h") }}
    {{ tile("DM water used", n2((D.dm_c|float) / 24) ~ " KL/hr", "Produced " ~ n2((D.dm_p|float) / 24) ~ " KL/hr") }}
  </tr></table>

  <table class="row"><tr>
    {% set dri_pts = [] %}{% set mw_pts = [] %}
    {% for i in range(day.day) %}{% set dt = U.add_days(mstart, i) %}{% set r = pd.get(dt|string) %}
      {% set v = (r.dri|float) if r else 0 %}{% set _ = dri_pts.append({"l": dt.day, "v": v, "ok": v >= target_day}) %}
      {% set mw = ((r.kwh|float) / 24000) if r else 0 %}{% set _ = mw_pts.append({"l": dt.day, "v": mw, "ok": mw >= TARGET_MW}) %}
    {% endfor %}
    <td class="panel first" style="width:50%"><div class="box">
      <div class="p-title">DRI this month · day by day</div>
      {{ chart(dri_pts, target_day, "MT", "DRI MT") }}
    </div></td>
    <td class="panel last" style="width:50%"><div class="box">
      <div class="p-title">Power this month · day by day</div>
      {{ chart(mw_pts, TARGET_MW, "MW", "Avg MW") }}
    </div></td>
  </tr></table>

  <table class="row"><tr>
    <td class="panel first" style="width:52%"><div class="box">
      <div class="p-title">DRI by kiln · day</div>
      <table class="grid">
        <tr><th class="l">Kiln</th><th>DRI MT</th><th>Pellet yld %</th><th>Ore yld %</th><th>"A" %</th><th>Sp. coal</th><th>Sp. iron</th><th>F.C. %</th><th>Fe(M) %</th><th>C %</th><th>S %</th><th class="sep">MTD MT</th><th>MTD MT/day</th></tr>
        {% macro dri_row(r, m) %}<td>{{ n0(r.dri) }}</td><td>{{ div(r.pel_p, r.pel, "n1", 100) }}</td><td>{{ div(r.ore_p, r.ore, "n1", 100) }}</td><td>{{ div(r.a_hrs, r.ab_hrs, "n1", 100) }}</td><td>{{ div(r.coal, r.dri) }}</td><td>{{ div(r.iron, r.dri) }}</td><td>{{ div(r.fc_num, r.coal, "n1") }}</td><td>{{ div(r.fe_num, r.fe_den) }}</td><td>{{ div(r.c_num, r.c_den) }}</td><td>{{ div(r.s_num, r.s_den, "n3") }}</td><td class="sep">{{ n0(m.dri) if m else "–" }}</td><td>{{ div(m.dri, m.days, "n1") if m else "–" }}</td>{% endmacro %}
        {% if k_day|length > 1 %}<tr class="total"><td class="l">All kilns</td>{{ dri_row(D, M) }}</tr>{% endif %}
        {% for r in k_day %}<tr><td class="l">{{ r.kiln }}</td>{{ dri_row(r, km.get(r.kiln)) }}</tr>{% endfor %}
        {% if not k_day %}<tr><td class="l muted" colspan="13">No production report for this day.</td></tr>{% endif %}
      </table>
    </div></td>
    <td class="panel last" style="width:48%"><div class="box">
      <div class="p-title">Power plant by kiln · day</div>
      <table class="grid">
        <tr><th class="l">Kiln</th><th>Avg MW</th><th>Import MWh</th><th>Export MWh</th><th>Aux %</th><th>Steam TPH</th><th>SSC</th><th>PLF</th><th>PF</th><th>TG h</th><th>WHRB h</th><th>DG h</th></tr>
        {% macro pp_row(r) %}<td>{{ n2((r.kwh|float) / 24000) }}</td><td>{{ n1((r.imp_kwh|float) / 1000) }}</td><td>{{ n1((r.exp_kwh|float) / 1000) }}</td><td>{{ div(r.pp_kwh, r.kwh, "n1", 100) }}</td><td>{{ n1((r.steam|float) / 24) }}</td><td>{{ div(r.stt, (r.kwh|float) / 1000) }}</td><td>{{ n2(r.plf) }}</td><td>{{ n2(r.pf) }}</td><td>{{ n1(r.tg) }}</td><td>{{ n1(r.whrb) }}</td><td>{{ n1(r.dg) }}</td>{% endmacro %}
        {% if k_day|length > 1 %}<tr class="total"><td class="l">All kilns</td>{{ pp_row(D) }}</tr>{% endif %}
        {% for r in k_day %}<tr><td class="l">{{ r.kiln }}</td>{{ pp_row(r) }}</tr>{% endfor %}
        {% if not k_day %}<tr><td class="l muted" colspan="12">No production report for this day.</td></tr>{% endif %}
      </table>
    </div></td>
  </tr></table>

  <table><tr>
    <td class="panel first" style="width:52%">{{ notes_box("Remarks · DRI", dri_notes, "No remarks on the day's reports.") }}</td>
    <td class="panel last" style="width:48%">{{ notes_box("Stoppages & breakdowns · power plant", pp_notes, "No breakdowns recorded on the day's reports.") }}</td>
  </tr></table>
</div>

{# ===================== PAGE 2 · SALES ===================== #}
{% set AGE_LABELS = ["Not due", "1–" ~ AGE_DAYS[0], (AGE_DAYS[0] + 1) ~ "–" ~ AGE_DAYS[1], (AGE_DAYS[1] + 1) ~ "–" ~ AGE_DAYS[2], "> " ~ AGE_DAYS[2]] %}
<div class="slide">
  {{ head("Sales · " ~ items_label, "Submitted invoices and orders of at least ₹" ~ n0(MIN_DOC_VALUE) ~ " net · values net of tax · receivables cover all invoices, as of " ~ frappe.format_date(next_day, "dd MMM") ~ " morning") }}
  <table class="tiles"><tr>
    {{ tile("Invoiced · day", inr(S.d_amt), n0(S.d_mt) ~ " MT · " ~ S.d_n ~ " invoices · " ~ inv_day|length ~ " customers") }}
    {{ tile("Invoiced · MTD", inr(S.m_amt), n0(S.m_mt) ~ " MT · " ~ S.m_n ~ " invoices") }}
    {{ tile("Average rate", ("₹" ~ div(S.d_wamt, S.d_mt, "n0") ~ "/MT") if S.d_mt > 0 else "–", "Day · MTD " ~ (("₹" ~ div(S.m_wamt, S.m_mt, "n0") ~ "/MT") if S.m_mt > 0 else "–")) }}
    {{ tile("Orders booked", inr(booked.d_amt), n0(booked.d_mt) ~ " MT today · MTD " ~ inr(booked.m_amt) ~ ", " ~ n0(booked.m_mt) ~ " MT") }}
    {{ tile("Pending to deliver", n0(P.mt) ~ " MT", inr(P.amt) ~ " · " ~ P.n ~ " open orders") }}
    {{ tile("Delivery overdue", n0(P.late) ~ " MT", "Pending past the order's delivery date", "warn" if P.late > 0 else "good") }}
    {{ tile("Receivables overdue", inr(R.overdue), div(R.overdue, R.owed, "n0", 100) ~ "% of " ~ inr(R.owed) ~ " owed · all items", "bad" if R.b4 > 0 else ("warn" if R.overdue > 0 else "good")) }}
    {{ tile("Oldest overdue", (R.oldest ~ " days") if R.oldest else "–", R.n_over ~ " invoices past due") }}
  </tr></table>

  <table class="row"><tr>
    <td class="panel first" style="width:45%"><div class="box">
      <div class="p-title">Invoiced today · {{ items_label }} · by customer</div>
      <table class="grid">
        <tr><th class="l">Customer</th><th>Invoices</th><th>MT</th><th>Value ₹ Cr</th><th>₹/MT</th><th class="sep">MTD MT</th><th>MTD ₹ Cr</th></tr>
        {% if inv_day %}<tr class="total"><td class="l">Total</td><td>{{ S.d_n }}</td><td>{{ n1(S.d_mt) }}</td><td>{{ cr(S.d_amt) }}</td><td>{{ div(S.d_wamt, S.d_mt, "n0") }}</td><td class="sep">{{ n0(S.m_mt) }}</td><td>{{ cr(S.m_amt) }}</td></tr>{% endif %}
        {% for r in inv_day[:12] %}<tr><td class="l clip">{{ r.name }}</td><td>{{ r.d_n }}</td><td>{{ n1(r.d_mt) }}</td><td>{{ cr(r.d_amt) }}</td><td>{{ div(r.d_wamt, r.d_mt, "n0") }}</td><td class="sep">{{ n0(r.m_mt) }}</td><td>{{ cr(r.m_amt) }}</td></tr>{% endfor %}
        {% if not inv_day %}<tr><td class="l muted" colspan="7">No {{ items_label }} invoices on this day.</td></tr>{% endif %}
      </table>
      {% if inv_day|length > 12 %}<div class="muted">+ {{ inv_day|length - 12 }} more customers</div>{% endif %}
    </div></td>
    <td class="panel last" style="width:55%"><div class="box">
      <div class="p-title">Pending sales orders · {{ items_label }} · MT</div>
      <table class="grid">
        <tr><th class="l">Customer</th><th class="l">Oldest</th><th class="l">Due</th><th>Ordered</th><th>Delivered</th><th>Pending</th><th>Overdue</th><th>Pending ₹ Cr</th></tr>
        {% if pend %}<tr class="total"><td class="l">Total</td><td></td><td></td><td>{{ n1(pend|sum(attribute="ord_mt")) }}</td><td>{{ n1(pend|sum(attribute="del_mt")) }}</td><td>{{ n1(P.mt) }}</td><td>{{ n1(P.late) }}</td><td>{{ cr(P.amt) }}</td></tr>{% endif %}
        {% for r in pend[:12] %}<tr><td class="l clip">{{ r.name }}</td><td class="l">{{ frappe.format_date(r.oldest, "dd MMM yy") }}</td><td class="l">{{ frappe.format_date(r.due, "dd MMM yy") if r.due else "–" }}</td><td>{{ n1(r.ord_mt) }}</td><td>{{ n1(r.del_mt) }}</td><td>{{ n1(r.pend_mt) }}</td><td>{{ n1(r.late_mt) }}</td><td>{{ cr(r.pend_amt) }}</td></tr>{% endfor %}
        {% if not pend %}<tr><td class="l muted" colspan="8">No open sales orders for {{ items_label }}.</td></tr>{% endif %}
      </table>
      {% if pend|length > 12 %}<div class="muted">+ {{ pend|length - 12 }} more customers</div>{% endif %}
    </div></td>
  </tr></table>

  <table class="row"><tr>
    <td class="panel first" style="width:30%"><div class="box">
      <div class="p-title">Receivables ageing · ₹ Cr</div>
      <div class="p-note">Outstanding {{ inr(R.amt) }} on {{ R.n }} invoices · days past due date</div>
      {{ hbars([
        {"l": "Not yet due", "v": R.b0, "t": cr(R.b0), "q": 1},
        {"l": AGE_LABELS[1] ~ " days", "v": R.b1, "t": cr(R.b1)},
        {"l": AGE_LABELS[2] ~ " days", "v": R.b2, "t": cr(R.b2)},
        {"l": AGE_LABELS[3] ~ " days", "v": R.b3, "t": cr(R.b3)},
        {"l": AGE_LABELS[4] ~ " days", "v": R.b4, "t": cr(R.b4)}
      ], "Nothing outstanding.") }}
    </div></td>
    <td class="panel last" style="width:70%"><div class="box">
      <div class="p-title">Receivables summary · ₹ Cr · customers owing ₹{{ n0(MIN_OUTSTANDING / 100000) }} L or more</div>
      <table class="grid">
        <tr><th class="l">Customer</th><th>Invoices</th><th>Outstanding</th>{% for a in AGE_LABELS %}<th>{{ a }}</th>{% endfor %}<th>Oldest (days)</th></tr>
        {% if ar_big %}<tr class="total"><td class="l">Total listed</td><td>{{ ar_big|sum(attribute="n") }}</td><td>{{ cr(ar_big|sum(attribute="amt")) }}</td>{% for b in ["b0", "b1", "b2", "b3", "b4"] %}<td>{{ cr(ar_big|sum(attribute=b)) }}</td>{% endfor %}<td></td></tr>{% endif %}
        {% for r in ar_big[:8] %}<tr><td class="l clip">{{ r.name }}</td><td>{{ r.n }}</td><td>{{ cr(r.amt) }}</td>{% for b in ["b0", "b1", "b2", "b3", "b4"] %}<td>{{ cr(r[b]) }}</td>{% endfor %}<td>{{ r.oldest or "" }}</td></tr>{% endfor %}
