      </table>
      <div class="muted">{% if ar_big|length > 8 %}+ {{ ar_big|length - 8 }} more listed · {% endif %}{{ ar_small }} customers under ₹{{ n0(MIN_OUTSTANDING / 100000) }} L not shown</div>
    </div></td>
  </tr></table>
</div>

{# ===================== PAGE 3 · WEIGHBRIDGE ===================== #}
{% macro wb_table(block, mv, limit) %}
<table class="grid">
  <tr><th class="l">{{ "Material / party" if mv == "inward" else "Party" }}</th><th>Trucks</th><th>Net MT</th><th>Avg TAT min</th></tr>
  <tr class="total"><td class="l">Total</td><td>{{ block.trucks }}</td><td>{{ n1(block.mt) }}</td><td>{{ n0(block.tat) }}</td></tr>
  {% set ns = namespace(rows=0, hidden=0) %}
  {% for g in block.groups %}
    {% if ns.rows < limit %}{% set ns.rows = ns.rows + 1 %}<tr class="{{ 'group' if mv == 'inward' else '' }}"><td class="l clip">{{ g.name }}</td><td>{{ g.trucks }}</td><td>{{ n1(g.mt) }}</td><td>{{ n0(g.tat) }}</td></tr>{% else %}{% set ns.hidden = ns.hidden + 1 %}{% endif %}
    {% for p in g.parties %}
      {% if ns.rows < limit %}{% set ns.rows = ns.rows + 1 %}<tr><td class="l ind clip">{{ p.name }}</td><td>{{ p.trucks }}</td><td>{{ n1(p.mt) }}</td><td>{{ n0(p.tat) }}</td></tr>{% else %}{% set ns.hidden = ns.hidden + 1 %}{% endif %}
    {% endfor %}
  {% endfor %}
  {% if not block.groups %}<tr><td class="l muted" colspan="4">No {{ mv }} trucks completed in this window.</td></tr>{% endif %}
</table>
{% if ns.hidden %}<div class="muted">+ {{ ns.hidden }} more rows</div>{% endif %}
{% endmacro %}
<div class="slide">
  {{ head("Weighbridge", frappe.format_date(day, "dd MMM") ~ " 6 AM to " ~ frappe.format_date(next_day, "dd MMM") ~ " 6 AM · a truck counts when its second weighing is done") }}
  <table class="tiles"><tr>
    {{ tile("Weighments", wb|length, "Inward " ~ W.inward.trucks ~ " · outward " ~ W.outward.trucks ~ " · MTD " ~ wm|length) }}
    {{ tile("Inward", n0(W.inward.mt) ~ " MT", W.inward.trucks ~ " trucks · MTD " ~ n0(wm|selectattr("mv", "equalto", "inward")|sum(attribute="mt")) ~ " MT") }}
    {{ tile("Outward", n0(W.outward.mt) ~ " MT", W.outward.trucks ~ " trucks · MTD " ~ n0(wm|selectattr("mv", "equalto", "outward")|sum(attribute="mt")) ~ " MT") }}
    {{ tile("Average TAT", (n0(day_tats|sum / day_tats|length) ~ " min") if day_tats else "–", "MTD " ~ ((n0(wm_tats|sum / wm_tats|length) ~ " min") if wm_tats else "–")) }}
    {{ tile("Median TAT", qtl(day_tats, 0.5) ~ " min", "MTD " ~ qtl(wm_tats, 0.5) ~ " min") }}
    {{ tile("P90 TAT", qtl(day_tats, 0.9) ~ " min", "MTD " ~ qtl(wm_tats, 0.9) ~ " min") }}
    {{ tile("Pending", wait_n, "Waiting at 6 AM · inward " ~ wait.get("inward", 0) ~ " · outward " ~ wait.get("outward", 0), "warn" if wait_n > 0 else "") }}
    {{ tile("TAT unavailable", wb|length - day_tats|length, "Missing or out-of-order timestamps") }}
  </tr></table>

  <table class="row"><tr>
    <td class="panel first" style="width:52%"><div class="box"><div class="p-title">Inward · by material and party</div>{{ wb_table(W.inward, "inward", 26) }}</div></td>
    <td class="panel last" style="width:48%">
      <div class="box" style="margin-bottom:6px"><div class="p-title">Outward · by party</div>{{ wb_table(W.outward, "outward", 14) }}</div>
      <div class="box">
        <div class="p-title">TAT distribution</div>
        <div class="p-note">Completed weighments in the window</div>
        {% set bc = namespace(a=0, b=0, c=0, d=0, e=0) %}
        {% for t in day_tats %}{% if t <= 30 %}{% set bc.a = bc.a + 1 %}{% elif t <= 60 %}{% set bc.b = bc.b + 1 %}{% elif t <= 120 %}{% set bc.c = bc.c + 1 %}{% elif t <= 240 %}{% set bc.d = bc.d + 1 %}{% else %}{% set bc.e = bc.e + 1 %}{% endif %}{% endfor %}
        {{ hbars([{"l": "≤ 30 min", "v": bc.a, "t": bc.a}, {"l": "30–60 min", "v": bc.b, "t": bc.b}, {"l": "60–120 min", "v": bc.c, "t": bc.c}, {"l": "120–240 min", "v": bc.d, "t": bc.d}, {"l": "> 240 min", "v": bc.e, "t": bc.e}], "No completed weighments.") }}
      </div>
    </td>
  </tr></table>
</div>

</div>
